INSERT IGNORE INTO graha_bhava_rashi (graha_id, bhava_id, rashi_id, interpretation_np, interpretation_en, positive_effects, challenges, career_indication, financial_indication, relationship_indication, classical_interpretation, sanskrit_reference, remedies) VALUES
(7,1,1,'शनि लग्नमा व्यक्ति अनुशासित, धैर्यवान र गम्भीर हुन्छ। सानो उमेरमा कठिनाइ तर पछि ठूलो उन्नति हुन्छ। शनिको मेष राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'धैर्य, अनुशासन, दृढ संकल्प, दीर्घायु, साहस','सानो उमेरमा कठिनाइ, अवसाद, हड्डी पीडा, जल्दबाजी','खनन, लोहा, कृषि, प्रशासन','ढिलो तर स्थिर आय, आत्मप्रयासबाट आय','विवाहमा ढिला, जीवनसाथी वयोवृद्ध, ऊर्जावान तर धैर्य कम','शनिर्लग्ने कर्तव्यपरायणः भवति। शनिः मेषे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 15','शनिवार शनि मन्त्र जप्ने र तिल तेल दान।'),
(7,1,2,'शनि लग्नमा व्यक्ति अनुशासित, धैर्यवान र गम्भीर हुन्छ। सानो उमेरमा कठिनाइ तर पछि ठूलो उन्नति हुन्छ। शनिको वृषभ राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'धैर्य, अनुशासन, दृढ संकल्प, दीर्घायु, संचय','सानो उमेरमा कठिनाइ, अवसाद, हड्डी पीडा, जिद','खनन, लोहा, कृषि, प्रशासन','ढिलो तर स्थिर आय, बचत र भूमि लाभ','विवाहमा ढिला, जीवनसाथी वयोवृद्ध, वफादार र शान्त','शनिर्लग्ने कर्तव्यपरायणः भवति। शनिः वृषभे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 15','शनिवार शनि मन्त्र जप्ने र तिल तेल दान।'),
(7,1,3,'शनि लग्नमा व्यक्ति अनुशासित, धैर्यवान र गम्भीर हुन्छ। सानो उमेरमा कठिनाइ तर पछि ठूलो उन्नति हुन्छ। शनिको मिथुन राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'धैर्य, अनुशासन, दृढ संकल्प, दीर्घायु, वाणी','सानो उमेरमा कठिनाइ, अवसाद, हड्डी पीडा, द्विधा','खनन, लोहा, कृषि, प्रशासन','ढिलो तर स्थिर आय, बहुआय, अनियमित','विवाहमा ढिला, जीवनसाथी वयोवृद्ध, मैत्रीपूर्ण तर भावना चञ्चल','शनिर्लग्ने कर्तव्यपरायणः भवति। शनिः मिथुने फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 15','शनिवार शनि मन्त्र जप्ने र तिल तेल दान।'),
(7,1,4,'शनि लग्नमा व्यक्ति अनुशासित, धैर्यवान र गम्भीर हुन्छ। सानो उमेरमा कठिनाइ तर पछि ठूलो उन्नति हुन्छ। शनिको कर्क राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'धैर्य, अनुशासन, दृढ संकल्प, दीर्घायु, करुणा','सानो उमेरमा कठिनाइ, अवसाद, हड्डी पीडा, मनोद्वन्द्व','खनन, लोहा, कृषि, प्रशासन','ढिलो तर स्थिर आय, चल सम्पत्ति, जलजन्य आय','विवाहमा ढिला, जीवनसाथी वयोवृद्ध, गहिरो स्नेह र ममता','शनिर्लग्ने कर्तव्यपरायणः भवति। शनिः कर्के फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 15','शनिवार शनि मन्त्र जप्ने र तिल तेल दान।'),
(7,1,5,'शनि लग्नमा व्यक्ति अनुशासित, धैर्यवान र गम्भीर हुन्छ। सानो उमेरमा कठिनाइ तर पछि ठूलो उन्नति हुन्छ। शनिको सिंह राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'धैर्य, अनुशासन, दृढ संकल्प, दीर्घायु, नेतृत्व','सानो उमेरमा कठिनाइ, अवसाद, हड्डी पीडा, अहंकार','खनन, लोहा, कृषि, प्रशासन','ढिलो तर स्थिर आय, उदार खर्चसँगै प्रतिष्ठाजनक आय','विवाहमा ढिला, जीवनसाथी वयोवृद्ध, आदर चाहने','शनिर्लग्ने कर्तव्यपरायणः भवति। शनिः सिंहे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 15','शनिवार शनि मन्त्र जप्ने र तिल तेल दान।'),
(7,1,6,'शनि लग्नमा व्यक्ति अनुशासित, धैर्यवान र गम्भीर हुन्छ। सानो उमेरमा कठिनाइ तर पछि ठूलो उन्नति हुन्छ। शनिको कन्या राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'धैर्य, अनुशासन, दृढ संकल्प, दीर्घायु, विश्लेषण','सानो उमेरमा कठिनाइ, अवसाद, हड्डी पीडा, आलोचनात्मकता','खनन, लोहा, कृषि, प्रशासन','ढिलो तर स्थिर आय, योजनाबद्ध बचत','विवाहमा ढिला, जीवनसाथी वयोवृद्ध, व्यावहारिक स्नेह','शनिर्लग्ने कर्तव्यपरायणः भवति। शनिः कन्यायां फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 15','शनिवार शनि मन्त्र जप्ने र तिल तेल दान।'),
(7,1,7,'शनि लग्नमा व्यक्ति अनुशासित, धैर्यवान र गम्भीर हुन्छ। सानो उमेरमा कठिनाइ तर पछि ठूलो उन्नति हुन्छ। शनिको तुला राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'धैर्य, अनुशासन, दृढ संकल्प, दीर्घायु, न्याय','सानो उमेरमा कठिनाइ, अवसाद, हड्डी पीडा, निर्णय ढिलाइ','खनन, लोहा, कृषि, प्रशासन','ढिलो तर स्थिर आय, सन्तुलित आय','विवाहमा ढिला, जीवनसाथी वयोवृद्ध, सामञ्जस्यपूर्ण जीवनसाथी','शनिर्लग्ने कर्तव्यपरायणः भवति। शनिः तुलायां फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 15','शनिवार शनि मन्त्र जप्ने र तिल तेल दान।'),
(7,1,8,'शनि लग्नमा व्यक्ति अनुशासित, धैर्यवान र गम्भीर हुन्छ। सानो उमेरमा कठिनाइ तर पछि ठूलो उन्नति हुन्छ। शनिको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'धैर्य, अनुशासन, दृढ संकल्प, दीर्घायु, अन्तर्दृष्टि','सानो उमेरमा कठिनाइ, अवसाद, हड्डी पीडा, षड्यन्त्रवाद','खनन, लोहा, कृषि, प्रशासन','ढिलो तर स्थिर आय, अचानक उतारचढाव','विवाहमा ढिला, जीवनसाथी वयोवृद्ध, गहिरो तर तीव्र','शनिर्लग्ने कर्तव्यपरायणः भवति। शनिः वृश्चिके फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 15','शनिवार शनि मन्त्र जप्ने र तिल तेल दान।'),
(7,1,9,'शनि लग्नमा व्यक्ति अनुशासित, धैर्यवान र गम्भीर हुन्छ। सानो उमेरमा कठिनाइ तर पछि ठूलो उन्नति हुन्छ। शनिको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'धैर्य, अनुशासन, दृढ संकल्प, दीर्घायु, ज्ञान','सानो उमेरमा कठिनाइ, अवसाद, हड्डी पीडा, अति विश्वास','खनन, लोहा, कृषि, प्रशासन','ढिलो तर स्थिर आय, भाग्यबाट लाभ, उदार खर्च','विवाहमा ढिला, जीवनसाथी वयोवृद्ध, स्वतन्त्रता दिने','शनिर्लग्ने कर्तव्यपरायणः भवति। शनिः धनौ फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 15','शनिवार शनि मन्त्र जप्ने र तिल तेल दान।'),
(7,1,10,'शनि लग्नमा व्यक्ति अनुशासित, धैर्यवान र गम्भीर हुन्छ। सानो उमेरमा कठिनाइ तर पछि ठूलो उन्नति हुन्छ। शनिको मकर राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'धैर्य, अनुशासन, दृढ संकल्प, दीर्घायु, कर्मठता','सानो उमेरमा कठिनाइ, अवसाद, हड्डी पीडा, निराशावाद','खनन, लोहा, कृषि, प्रशासन','ढिलो तर स्थिर आय, हौले हौले सम्पत्ति','विवाहमा ढिला, जीवनसाथी वयोवृद्ध, जिम्मेवार तर शब्द कम','शनिर्लग्ने कर्तव्यपरायणः भवति। शनिः मकरे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 15','शनिवार शनि मन्त्र जप्ने र तिल तेल दान।'),
(7,1,11,'शनि लग्नमा व्यक्ति अनुशासित, धैर्यवान र गम्भीर हुन्छ। सानो उमेरमा कठिनाइ तर पछि ठूलो उन्नति हुन्छ। शनिको कुम्भ राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'धैर्य, अनुशासन, दृढ संकल्प, दीर्घायु, नवप्रवर्तन','सानो उमेरमा कठिनाइ, अवसाद, हड्डी पीडा, विद्रोहीपन','खनन, लोहा, कृषि, प्रशासन','ढिलो तर स्थिर आय, नवीन तर अनियमित स्रोत','विवाहमा ढिला, जीवनसाथी वयोवृद्ध, मित्रतामा आधारित','शनिर्लग्ने कर्तव्यपरायणः भवति। शनिः कुम्भे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 15','शनिवार शनि मन्त्र जप्ने र तिल तेल दान।'),
(7,1,12,'शनि लग्नमा व्यक्ति अनुशासित, धैर्यवान र गम्भीर हुन्छ। सानो उमेरमा कठिनाइ तर पछि ठूलो उन्नति हुन्छ। शनिको मीन राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'धैर्य, अनुशासन, दृढ संकल्प, दीर्घायु, कल्पनाशक्ति','सानो उमेरमा कठिनाइ, अवसाद, हड्डी पीडा, अस्पष्टता','खनन, लोहा, कृषि, प्रशासन','ढिलो तर स्थिर आय, स्रोत अनिश्चित, दानशीलता','विवाहमा ढिला, जीवनसाथी वयोवृद्ध, निःशर्त प्रेम','शनिर्लग्ने कर्तव्यपरायणः भवति। शनिः मीने फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 15','शनिवार शनि मन्त्र जप्ने र तिल तेल दान।'),
(7,2,1,'शनि दोस्रो भावमा परिश्रमबाट कमाएको धन दिन्छ। बचत ढिलाइपछि हुन्छ तर स्थिर हुन्छ। वाणी गम्भीर र कडा हुन्छ, परिवारमा जिम्मेवारी र संयमको वातावरण रहन्छ। शनिको मेष राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'दिगो बचत, परिश्रम धन, जिम्मेवारी, संयम, साहस','वाणी कडापन, धनमा ढिलाइ, परिवारमा कठोरता, जल्दबाजी','खनन, कृषि, लेखा, श्रम सम्बन्ध','ढिलो तर स्थिर सम्पत्ति, मुद्रा बचत, आत्मप्रयासबाट आय','परिवारमा गम्भीर तर जिम्मेवार व्यवहार, ऊर्जावान तर धैर्य कम','द्वितीयस्थो शनिर्धनवान् भवति। शनिः मेषे फलं वर्धयति।','Phaladeepika','शनिवार तिल तेल दान र शनि मन्त्र जप।'),
(7,2,2,'शनि दोस्रो भावमा परिश्रमबाट कमाएको धन दिन्छ। बचत ढिलाइपछि हुन्छ तर स्थिर हुन्छ। वाणी गम्भीर र कडा हुन्छ, परिवारमा जिम्मेवारी र संयमको वातावरण रहन्छ। शनिको वृषभ राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'दिगो बचत, परिश्रम धन, जिम्मेवारी, संयम, धैर्य','वाणी कडापन, धनमा ढिलाइ, परिवारमा कठोरता, जिद','खनन, कृषि, लेखा, श्रम सम्बन्ध','ढिलो तर स्थिर सम्पत्ति, मुद्रा बचत, बचत र भूमि लाभ','परिवारमा गम्भीर तर जिम्मेवार व्यवहार, वफादार र शान्त','द्वितीयस्थो शनिर्धनवान् भवति। शनिः वृषभे फलं वर्धयति।','Phaladeepika','शनिवार तिल तेल दान र शनि मन्त्र जप।'),
(7,2,3,'शनि दोस्रो भावमा परिश्रमबाट कमाएको धन दिन्छ। बचत ढिलाइपछि हुन्छ तर स्थिर हुन्छ। वाणी गम्भीर र कडा हुन्छ, परिवारमा जिम्मेवारी र संयमको वातावरण रहन्छ। शनिको मिथुन राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'दिगो बचत, परिश्रम धन, जिम्मेवारी, संयम, वाणी','वाणी कडापन, धनमा ढिलाइ, परिवारमा कठोरता, द्विधा','खनन, कृषि, लेखा, श्रम सम्बन्ध','ढिलो तर स्थिर सम्पत्ति, मुद्रा बचत, बहुआय','परिवारमा गम्भीर तर जिम्मेवार व्यवहार, मैत्रीपूर्ण तर भावना चञ्चल','द्वितीयस्थो शनिर्धनवान् भवति। शनिः मिथुने फलं वर्धयति।','Phaladeepika','शनिवार तिल तेल दान र शनि मन्त्र जप।'),
(7,2,4,'शनि दोस्रो भावमा परिश्रमबाट कमाएको धन दिन्छ। बचत ढिलाइपछि हुन्छ तर स्थिर हुन्छ। वाणी गम्भीर र कडा हुन्छ, परिवारमा जिम्मेवारी र संयमको वातावरण रहन्छ। शनिको कर्क राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'दिगो बचत, परिश्रम धन, जिम्मेवारी, संयम, करुणा','वाणी कडापन, धनमा ढिलाइ, परिवारमा कठोरता, मनोद्वन्द्व','खनन, कृषि, लेखा, श्रम सम्बन्ध','ढिलो तर स्थिर सम्पत्ति, मुद्रा बचत, चल सम्पत्ति','परिवारमा गम्भीर तर जिम्मेवार व्यवहार, गहिरो स्नेह र ममता','द्वितीयस्थो शनिर्धनवान् भवति। शनिः कर्के फलं वर्धयति।','Phaladeepika','शनिवार तिल तेल दान र शनि मन्त्र जप।'),
(7,2,5,'शनि दोस्रो भावमा परिश्रमबाट कमाएको धन दिन्छ। बचत ढिलाइपछि हुन्छ तर स्थिर हुन्छ। वाणी गम्भीर र कडा हुन्छ, परिवारमा जिम्मेवारी र संयमको वातावरण रहन्छ। शनिको सिंह राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'दिगो बचत, परिश्रम धन, जिम्मेवारी, संयम, नेतृत्व','वाणी कडापन, धनमा ढिलाइ, परिवारमा कठोरता, अहंकार','खनन, कृषि, लेखा, श्रम सम्बन्ध','ढिलो तर स्थिर सम्पत्ति, मुद्रा बचत, उदार खर्चसँगै प्रतिष्ठाजनक आय','परिवारमा गम्भीर तर जिम्मेवार व्यवहार, आदर चाहने, उदार','द्वितीयस्थो शनिर्धनवान् भवति। शनिः सिंहे फलं वर्धयति।','Phaladeepika','शनिवार तिल तेल दान र शनि मन्त्र जप।'),
(7,2,6,'शनि दोस्रो भावमा परिश्रमबाट कमाएको धन दिन्छ। बचत ढिलाइपछि हुन्छ तर स्थिर हुन्छ। वाणी गम्भीर र कडा हुन्छ, परिवारमा जिम्मेवारी र संयमको वातावरण रहन्छ। शनिको कन्या राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'दिगो बचत, परिश्रम धन, जिम्मेवारी, संयम, विश्लेषण','वाणी कडापन, धनमा ढिलाइ, परिवारमा कठोरता, आलोचनात्मकता','खनन, कृषि, लेखा, श्रम सम्बन्ध','ढिलो तर स्थिर सम्पत्ति, मुद्रा बचत, योजनाबद्ध बचत','परिवारमा गम्भीर तर जिम्मेवार व्यवहार, व्यावहारिक स्नेह, सेवा','द्वितीयस्थो शनिर्धनवान् भवति। शनिः कन्यायां फलं वर्धयति।','Phaladeepika','शनिवार तिल तेल दान र शनि मन्त्र जप।'),
(7,2,7,'शनि दोस्रो भावमा परिश्रमबाट कमाएको धन दिन्छ। बचत ढिलाइपछि हुन्छ तर स्थिर हुन्छ। वाणी गम्भीर र कडा हुन्छ, परिवारमा जिम्मेवारी र संयमको वातावरण रहन्छ। शनिको तुला राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'दिगो बचत, परिश्रम धन, जिम्मेवारी, संयम, न्याय','वाणी कडापन, धनमा ढिलाइ, परिवारमा कठोरता, निर्णय ढिलाइ','खनन, कृषि, लेखा, श्रम सम्बन्ध','ढिलो तर स्थिर सम्पत्ति, मुद्रा बचत, सन्तुलित आय','परिवारमा गम्भीर तर जिम्मेवार व्यवहार, सामञ्जस्यपूर्ण जीवनसाथी','द्वितीयस्थो शनिर्धनवान् भवति। शनिः तुलायां फलं वर्धयति।','Phaladeepika','शनिवार तिल तेल दान र शनि मन्त्र जप।'),
(7,2,8,'शनि दोस्रो भावमा परिश्रमबाट कमाएको धन दिन्छ। बचत ढिलाइपछि हुन्छ तर स्थिर हुन्छ। वाणी गम्भीर र कडा हुन्छ, परिवारमा जिम्मेवारी र संयमको वातावरण रहन्छ। शनिको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'दिगो बचत, परिश्रम धन, जिम्मेवारी, संयम, अन्तर्दृष्टि','वाणी कडापन, धनमा ढिलाइ, परिवारमा कठोरता, षड्यन्त्रवाद','खनन, कृषि, लेखा, श्रम सम्बन्ध','ढिलो तर स्थिर सम्पत्ति, मुद्रा बचत, अचानक उतारचढाव','परिवारमा गम्भीर तर जिम्मेवार व्यवहार, गहिरो तर तीव्र','द्वितीयस्थो शनिर्धनवान् भवति। शनिः वृश्चिके फलं वर्धयति।','Phaladeepika','शनिवार तिल तेल दान र शनि मन्त्र जप।'),
(7,2,9,'शनि दोस्रो भावमा परिश्रमबाट कमाएको धन दिन्छ। बचत ढिलाइपछि हुन्छ तर स्थिर हुन्छ। वाणी गम्भीर र कडा हुन्छ, परिवारमा जिम्मेवारी र संयमको वातावरण रहन्छ। शनिको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'दिगो बचत, परिश्रम धन, जिम्मेवारी, संयम, ज्ञान','वाणी कडापन, धनमा ढिलाइ, परिवारमा कठोरता, अति विश्वास','खनन, कृषि, लेखा, श्रम सम्बन्ध','ढिलो तर स्थिर सम्पत्ति, मुद्रा बचत, भाग्यबाट लाभ','परिवारमा गम्भीर तर जिम्मेवार व्यवहार, स्वतन्त्रता दिने','द्वितीयस्थो शनिर्धनवान् भवति। शनिः धनौ फलं वर्धयति।','Phaladeepika','शनिवार तिल तेल दान र शनि मन्त्र जप।'),
(7,2,10,'शनि दोस्रो भावमा परिश्रमबाट कमाएको धन दिन्छ। बचत ढिलाइपछि हुन्छ तर स्थिर हुन्छ। वाणी गम्भीर र कडा हुन्छ, परिवारमा जिम्मेवारी र संयमको वातावरण रहन्छ। शनिको मकर राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'दिगो बचत, परिश्रम धन, जिम्मेवारी, संयम, कर्मठता','वाणी कडापन, धनमा ढिलाइ, परिवारमा कठोरता, निराशावाद','खनन, कृषि, लेखा, श्रम सम्बन्ध','ढिलो तर स्थिर सम्पत्ति, मुद्रा बचत, हौले हौले सम्पत्ति','परिवारमा गम्भीर तर जिम्मेवार व्यवहार, जिम्मेवार तर शब्द कम','द्वितीयस्थो शनिर्धनवान् भवति। शनिः मकरे फलं वर्धयति।','Phaladeepika','शनिवार तिल तेल दान र शनि मन्त्र जप।'),
(7,2,11,'शनि दोस्रो भावमा परिश्रमबाट कमाएको धन दिन्छ। बचत ढिलाइपछि हुन्छ तर स्थिर हुन्छ। वाणी गम्भीर र कडा हुन्छ, परिवारमा जिम्मेवारी र संयमको वातावरण रहन्छ। शनिको कुम्भ राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'दिगो बचत, परिश्रम धन, जिम्मेवारी, संयम, नवप्रवर्तन','वाणी कडापन, धनमा ढिलाइ, परिवारमा कठोरता, विद्रोहीपन','खनन, कृषि, लेखा, श्रम सम्बन्ध','ढिलो तर स्थिर सम्पत्ति, मुद्रा बचत, नवीन तर अनियमित स्रोत','परिवारमा गम्भीर तर जिम्मेवार व्यवहार, मित्रतामा आधारित','द्वितीयस्थो शनिर्धनवान् भवति। शनिः कुम्भे फलं वर्धयति।','Phaladeepika','शनिवार तिल तेल दान र शनि मन्त्र जप।'),
(7,2,12,'शनि दोस्रो भावमा परिश्रमबाट कमाएको धन दिन्छ। बचत ढिलाइपछि हुन्छ तर स्थिर हुन्छ। वाणी गम्भीर र कडा हुन्छ, परिवारमा जिम्मेवारी र संयमको वातावरण रहन्छ। शनिको मीन राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'दिगो बचत, परिश्रम धन, जिम्मेवारी, संयम, कल्पनाशक्ति','वाणी कडापन, धनमा ढिलाइ, परिवारमा कठोरता, अस्पष्टता','खनन, कृषि, लेखा, श्रम सम्बन्ध','ढिलो तर स्थिर सम्पत्ति, मुद्रा बचत, स्रोत अनिश्चित','परिवारमा गम्भीर तर जिम्मेवार व्यवहार, निःशर्त प्रेम, बलिदान','द्वितीयस्थो शनिर्धनवान् भवति। शनिः मीने फलं वर्धयति।','Phaladeepika','शनिवार तिल तेल दान र शनि मन्त्र जप।'),
(7,3,1,'शनि तेस्रो भावमा ढिलो तर दृढ साहस दिन्छ। भाइबहिनीप्रति कर्तव्यपरायणता रहन्छ। छोटो यात्रामा विलम्ब हुन सक्छ तर परिश्रमले काम पूरा गर्छ। शनिको मेष राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'दृढ साहस, कर्तव्यपरायणता, परिश्रम, धैर्य, साहस','यात्रा विलम्ब, भाइबहिनीसँग दूरी, उदासी, जल्दबाजी','खनन, श्रम, प्रशासन, लेखन','परिश्रमबाट ढिलो तर निश्चित आय, आत्मप्रयासबाट आय','भाइबहिनीसँग कर्तव्य सम्बन्ध, ऊर्जावान तर धैर्य कम','तृतीयस्थो शनिर्धैर्यवान् भवति। शनिः मेषे फलं वर्धयति।','Brihat Jataka','शनिवार शनि मन्त्र जप र काला तिल दान।'),
(7,3,2,'शनि तेस्रो भावमा ढिलो तर दृढ साहस दिन्छ। भाइबहिनीप्रति कर्तव्यपरायणता रहन्छ। छोटो यात्रामा विलम्ब हुन सक्छ तर परिश्रमले काम पूरा गर्छ। शनिको वृषभ राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'दृढ साहस, कर्तव्यपरायणता, परिश्रम, धैर्य, संचय','यात्रा विलम्ब, भाइबहिनीसँग दूरी, उदासी, जिद','खनन, श्रम, प्रशासन, लेखन','परिश्रमबाट ढिलो तर निश्चित आय, बचत र भूमि लाभ','भाइबहिनीसँग कर्तव्य सम्बन्ध, वफादार र शान्त','तृतीयस्थो शनिर्धैर्यवान् भवति। शनिः वृषभे फलं वर्धयति।','Brihat Jataka','शनिवार शनि मन्त्र जप र काला तिल दान।'),
(7,3,3,'शनि तेस्रो भावमा ढिलो तर दृढ साहस दिन्छ। भाइबहिनीप्रति कर्तव्यपरायणता रहन्छ। छोटो यात्रामा विलम्ब हुन सक्छ तर परिश्रमले काम पूरा गर्छ। शनिको मिथुन राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'दृढ साहस, कर्तव्यपरायणता, परिश्रम, धैर्य, वाणी','यात्रा विलम्ब, भाइबहिनीसँग दूरी, उदासी, द्विधा','खनन, श्रम, प्रशासन, लेखन','परिश्रमबाट ढिलो तर निश्चित आय, बहुआय, अनियमित','भाइबहिनीसँग कर्तव्य सम्बन्ध, मैत्रीपूर्ण तर भावना चञ्चल','तृतीयस्थो शनिर्धैर्यवान् भवति। शनिः मिथुने फलं वर्धयति।','Brihat Jataka','शनिवार शनि मन्त्र जप र काला तिल दान।'),
(7,3,4,'शनि तेस्रो भावमा ढिलो तर दृढ साहस दिन्छ। भाइबहिनीप्रति कर्तव्यपरायणता रहन्छ। छोटो यात्रामा विलम्ब हुन सक्छ तर परिश्रमले काम पूरा गर्छ। शनिको कर्क राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'दृढ साहस, कर्तव्यपरायणता, परिश्रम, धैर्य, करुणा','यात्रा विलम्ब, भाइबहिनीसँग दूरी, उदासी, मनोद्वन्द्व','खनन, श्रम, प्रशासन, लेखन','परिश्रमबाट ढिलो तर निश्चित आय, चल सम्पत्ति, जलजन्य आय','भाइबहिनीसँग कर्तव्य सम्बन्ध, गहिरो स्नेह र ममता','तृतीयस्थो शनिर्धैर्यवान् भवति। शनिः कर्के फलं वर्धयति।','Brihat Jataka','शनिवार शनि मन्त्र जप र काला तिल दान।'),
(7,3,5,'शनि तेस्रो भावमा ढिलो तर दृढ साहस दिन्छ। भाइबहिनीप्रति कर्तव्यपरायणता रहन्छ। छोटो यात्रामा विलम्ब हुन सक्छ तर परिश्रमले काम पूरा गर्छ। शनिको सिंह राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'दृढ साहस, कर्तव्यपरायणता, परिश्रम, धैर्य, नेतृत्व','यात्रा विलम्ब, भाइबहिनीसँग दूरी, उदासी, अहंकार','खनन, श्रम, प्रशासन, लेखन','परिश्रमबाट ढिलो तर निश्चित आय, उदार खर्चसँगै प्रतिष्ठाजनक आय','भाइबहिनीसँग कर्तव्य सम्बन्ध, आदर चाहने, उदार','तृतीयस्थो शनिर्धैर्यवान् भवति। शनिः सिंहे फलं वर्धयति।','Brihat Jataka','शनिवार शनि मन्त्र जप र काला तिल दान।'),
(7,3,6,'शनि तेस्रो भावमा ढिलो तर दृढ साहस दिन्छ। भाइबहिनीप्रति कर्तव्यपरायणता रहन्छ। छोटो यात्रामा विलम्ब हुन सक्छ तर परिश्रमले काम पूरा गर्छ। शनिको कन्या राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'दृढ साहस, कर्तव्यपरायणता, परिश्रम, धैर्य, विश्लेषण','यात्रा विलम्ब, भाइबहिनीसँग दूरी, उदासी, आलोचनात्मकता','खनन, श्रम, प्रशासन, लेखन','परिश्रमबाट ढिलो तर निश्चित आय, योजनाबद्ध बचत','भाइबहिनीसँग कर्तव्य सम्बन्ध, व्यावहारिक स्नेह, सेवा','तृतीयस्थो शनिर्धैर्यवान् भवति। शनिः कन्यायां फलं वर्धयति।','Brihat Jataka','शनिवार शनि मन्त्र जप र काला तिल दान।'),
(7,3,7,'शनि तेस्रो भावमा ढिलो तर दृढ साहस दिन्छ। भाइबहिनीप्रति कर्तव्यपरायणता रहन्छ। छोटो यात्रामा विलम्ब हुन सक्छ तर परिश्रमले काम पूरा गर्छ। शनिको तुला राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'दृढ साहस, कर्तव्यपरायणता, परिश्रम, धैर्य, न्याय','यात्रा विलम्ब, भाइबहिनीसँग दूरी, उदासी, निर्णय ढिलाइ','खनन, श्रम, प्रशासन, लेखन','परिश्रमबाट ढिलो तर निश्चित आय, सन्तुलित आय','भाइबहिनीसँग कर्तव्य सम्बन्ध, सामञ्जस्यपूर्ण जीवनसाथी','तृतीयस्थो शनिर्धैर्यवान् भवति। शनिः तुलायां फलं वर्धयति।','Brihat Jataka','शनिवार शनि मन्त्र जप र काला तिल दान।'),
(7,3,8,'शनि तेस्रो भावमा ढिलो तर दृढ साहस दिन्छ। भाइबहिनीप्रति कर्तव्यपरायणता रहन्छ। छोटो यात्रामा विलम्ब हुन सक्छ तर परिश्रमले काम पूरा गर्छ। शनिको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'दृढ साहस, कर्तव्यपरायणता, परिश्रम, धैर्य, अन्तर्दृष्टि','यात्रा विलम्ब, भाइबहिनीसँग दूरी, उदासी, षड्यन्त्रवाद','खनन, श्रम, प्रशासन, लेखन','परिश्रमबाट ढिलो तर निश्चित आय, अचानक उतारचढाव','भाइबहिनीसँग कर्तव्य सम्बन्ध, गहिरो तर तीव्र','तृतीयस्थो शनिर्धैर्यवान् भवति। शनिः वृश्चिके फलं वर्धयति।','Brihat Jataka','शनिवार शनि मन्त्र जप र काला तिल दान।'),
(7,3,9,'शनि तेस्रो भावमा ढिलो तर दृढ साहस दिन्छ। भाइबहिनीप्रति कर्तव्यपरायणता रहन्छ। छोटो यात्रामा विलम्ब हुन सक्छ तर परिश्रमले काम पूरा गर्छ। शनिको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'दृढ साहस, कर्तव्यपरायणता, परिश्रम, धैर्य, ज्ञान','यात्रा विलम्ब, भाइबहिनीसँग दूरी, उदासी, अति विश्वास','खनन, श्रम, प्रशासन, लेखन','परिश्रमबाट ढिलो तर निश्चित आय, भाग्यबाट लाभ, उदार खर्च','भाइबहिनीसँग कर्तव्य सम्बन्ध, स्वतन्त्रता दिने','तृतीयस्थो शनिर्धैर्यवान् भवति। शनिः धनौ फलं वर्धयति।','Brihat Jataka','शनिवार शनि मन्त्र जप र काला तिल दान।'),
(7,3,10,'शनि तेस्रो भावमा ढिलो तर दृढ साहस दिन्छ। भाइबहिनीप्रति कर्तव्यपरायणता रहन्छ। छोटो यात्रामा विलम्ब हुन सक्छ तर परिश्रमले काम पूरा गर्छ। शनिको मकर राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'दृढ साहस, कर्तव्यपरायणता, परिश्रम, धैर्य, कर्मठता','यात्रा विलम्ब, भाइबहिनीसँग दूरी, उदासी, निराशावाद','खनन, श्रम, प्रशासन, लेखन','परिश्रमबाट ढिलो तर निश्चित आय, हौले हौले सम्पत्ति','भाइबहिनीसँग कर्तव्य सम्बन्ध, जिम्मेवार तर शब्द कम','तृतीयस्थो शनिर्धैर्यवान् भवति। शनिः मकरे फलं वर्धयति।','Brihat Jataka','शनिवार शनि मन्त्र जप र काला तिल दान।'),
(7,3,11,'शनि तेस्रो भावमा ढिलो तर दृढ साहस दिन्छ। भाइबहिनीप्रति कर्तव्यपरायणता रहन्छ। छोटो यात्रामा विलम्ब हुन सक्छ तर परिश्रमले काम पूरा गर्छ। शनिको कुम्भ राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'दृढ साहस, कर्तव्यपरायणता, परिश्रम, धैर्य, नवप्रवर्तन','यात्रा विलम्ब, भाइबहिनीसँग दूरी, उदासी, विद्रोहीपन','खनन, श्रम, प्रशासन, लेखन','परिश्रमबाट ढिलो तर निश्चित आय, नवीन तर अनियमित स्रोत','भाइबहिनीसँग कर्तव्य सम्बन्ध, मित्रतामा आधारित','तृतीयस्थो शनिर्धैर्यवान् भवति। शनिः कुम्भे फलं वर्धयति।','Brihat Jataka','शनिवार शनि मन्त्र जप र काला तिल दान।'),
(7,3,12,'शनि तेस्रो भावमा ढिलो तर दृढ साहस दिन्छ। भाइबहिनीप्रति कर्तव्यपरायणता रहन्छ। छोटो यात्रामा विलम्ब हुन सक्छ तर परिश्रमले काम पूरा गर्छ। शनिको मीन राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'दृढ साहस, कर्तव्यपरायणता, परिश्रम, धैर्य, कल्पनाशक्ति','यात्रा विलम्ब, भाइबहिनीसँग दूरी, उदासी, अस्पष्टता','खनन, श्रम, प्रशासन, लेखन','परिश्रमबाट ढिलो तर निश्चित आय, स्रोत अनिश्चित, दानशीलता','भाइबहिनीसँग कर्तव्य सम्बन्ध, निःशर्त प्रेम, बलिदान','तृतीयस्थो शनिर्धैर्यवान् भवति। शनिः मीने फलं वर्धयति।','Brihat Jataka','शनिवार शनि मन्त्र जप र काला तिल दान।'),
(7,4,1,'शनि चौथो भावमा घर र सुखमा ढिलाइ ल्याउँछ। जग्गा-घर पछि मिल्छ, माता दीर्घायु हुन्छन् तर भावनात्मक शान्ति ढिलो मिल्छ। सादा र अनुशासित घर वातावरण रहन्छ। शनिको मेष राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'जग्गा-घर (ढिलाइपछि), माता आयु, अनुशासन, सादगी, साहस','सुख ढिलाइ, भावनात्मक एकान्तता, घर तनाव, जल्दबाजी','भवन निर्माण, कृषि, भण्डार, प्रशासन','जग्गाबाट ढिलो तर दिगो लाभ, आत्मप्रयासबाट आय','परिवारमा सादा र गम्भीर सम्बन्ध, ऊर्जावान तर धैर्य कम','चतुर्थस्थो शनिर्गृहं ददाति। शनिः मेषे फलं वर्धयति।','Saravali','शनिवार तिल तेल दान र शिवलिङ्गमा जल।'),
(7,4,2,'शनि चौथो भावमा घर र सुखमा ढिलाइ ल्याउँछ। जग्गा-घर पछि मिल्छ, माता दीर्घायु हुन्छन् तर भावनात्मक शान्ति ढिलो मिल्छ। सादा र अनुशासित घर वातावरण रहन्छ। शनिको वृषभ राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'जग्गा-घर (ढिलाइपछि), माता आयु, अनुशासन, सादगी, धैर्य','सुख ढिलाइ, भावनात्मक एकान्तता, घर तनाव, जिद','भवन निर्माण, कृषि, भण्डार, प्रशासन','जग्गाबाट ढिलो तर दिगो लाभ, बचत र भूमि लाभ','परिवारमा सादा र गम्भीर सम्बन्ध, वफादार र शान्त','चतुर्थस्थो शनिर्गृहं ददाति। शनिः वृषभे फलं वर्धयति।','Saravali','शनिवार तिल तेल दान र शिवलिङ्गमा जल।'),
(7,4,3,'शनि चौथो भावमा घर र सुखमा ढिलाइ ल्याउँछ। जग्गा-घर पछि मिल्छ, माता दीर्घायु हुन्छन् तर भावनात्मक शान्ति ढिलो मिल्छ। सादा र अनुशासित घर वातावरण रहन्छ। शनिको मिथुन राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'जग्गा-घर (ढिलाइपछि), माता आयु, अनुशासन, सादगी, वाणी','सुख ढिलाइ, भावनात्मक एकान्तता, घर तनाव, द्विधा','भवन निर्माण, कृषि, भण्डार, प्रशासन','जग्गाबाट ढिलो तर दिगो लाभ, बहुआय, अनियमित','परिवारमा सादा र गम्भीर सम्बन्ध, मैत्रीपूर्ण तर भावना चञ्चल','चतुर्थस्थो शनिर्गृहं ददाति। शनिः मिथुने फलं वर्धयति।','Saravali','शनिवार तिल तेल दान र शिवलिङ्गमा जल।'),
(7,4,4,'शनि चौथो भावमा घर र सुखमा ढिलाइ ल्याउँछ। जग्गा-घर पछि मिल्छ, माता दीर्घायु हुन्छन् तर भावनात्मक शान्ति ढिलो मिल्छ। सादा र अनुशासित घर वातावरण रहन्छ। शनिको कर्क राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'जग्गा-घर (ढिलाइपछि), माता आयु, अनुशासन, सादगी, करुणा','सुख ढिलाइ, भावनात्मक एकान्तता, घर तनाव, मनोद्वन्द्व','भवन निर्माण, कृषि, भण्डार, प्रशासन','जग्गाबाट ढिलो तर दिगो लाभ, चल सम्पत्ति, जलजन्य आय','परिवारमा सादा र गम्भीर सम्बन्ध, गहिरो स्नेह र ममता','चतुर्थस्थो शनिर्गृहं ददाति। शनिः कर्के फलं वर्धयति।','Saravali','शनिवार तिल तेल दान र शिवलिङ्गमा जल।'),
(7,4,5,'शनि चौथो भावमा घर र सुखमा ढिलाइ ल्याउँछ। जग्गा-घर पछि मिल्छ, माता दीर्घायु हुन्छन् तर भावनात्मक शान्ति ढिलो मिल्छ। सादा र अनुशासित घर वातावरण रहन्छ। शनिको सिंह राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'जग्गा-घर (ढिलाइपछि), माता आयु, अनुशासन, सादगी, नेतृत्व','सुख ढिलाइ, भावनात्मक एकान्तता, घर तनाव, अहंकार','भवन निर्माण, कृषि, भण्डार, प्रशासन','जग्गाबाट ढिलो तर दिगो लाभ, उदार खर्चसँगै प्रतिष्ठाजनक आय','परिवारमा सादा र गम्भीर सम्बन्ध, आदर चाहने, उदार','चतुर्थस्थो शनिर्गृहं ददाति। शनिः सिंहे फलं वर्धयति।','Saravali','शनिवार तिल तेल दान र शिवलिङ्गमा जल।'),
(7,4,6,'शनि चौथो भावमा घर र सुखमा ढिलाइ ल्याउँछ। जग्गा-घर पछि मिल्छ, माता दीर्घायु हुन्छन् तर भावनात्मक शान्ति ढिलो मिल्छ। सादा र अनुशासित घर वातावरण रहन्छ। शनिको कन्या राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'जग्गा-घर (ढिलाइपछि), माता आयु, अनुशासन, सादगी, विश्लेषण','सुख ढिलाइ, भावनात्मक एकान्तता, घर तनाव, आलोचनात्मकता','भवन निर्माण, कृषि, भण्डार, प्रशासन','जग्गाबाट ढिलो तर दिगो लाभ, योजनाबद्ध बचत','परिवारमा सादा र गम्भीर सम्बन्ध, व्यावहारिक स्नेह, सेवा','चतुर्थस्थो शनिर्गृहं ददाति। शनिः कन्यायां फलं वर्धयति।','Saravali','शनिवार तिल तेल दान र शिवलिङ्गमा जल।'),
(7,4,7,'शनि चौथो भावमा घर र सुखमा ढिलाइ ल्याउँछ। जग्गा-घर पछि मिल्छ, माता दीर्घायु हुन्छन् तर भावनात्मक शान्ति ढिलो मिल्छ। सादा र अनुशासित घर वातावरण रहन्छ। शनिको तुला राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'जग्गा-घर (ढिलाइपछि), माता आयु, अनुशासन, सादगी, न्याय','सुख ढिलाइ, भावनात्मक एकान्तता, घर तनाव, निर्णय ढिलाइ','भवन निर्माण, कृषि, भण्डार, प्रशासन','जग्गाबाट ढिलो तर दिगो लाभ, सन्तुलित आय','परिवारमा सादा र गम्भीर सम्बन्ध, सामञ्जस्यपूर्ण जीवनसाथी','चतुर्थस्थो शनिर्गृहं ददाति। शनिः तुलायां फलं वर्धयति।','Saravali','शनिवार तिल तेल दान र शिवलिङ्गमा जल।'),
(7,4,8,'शनि चौथो भावमा घर र सुखमा ढिलाइ ल्याउँछ। जग्गा-घर पछि मिल्छ, माता दीर्घायु हुन्छन् तर भावनात्मक शान्ति ढिलो मिल्छ। सादा र अनुशासित घर वातावरण रहन्छ। शनिको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'जग्गा-घर (ढिलाइपछि), माता आयु, अनुशासन, सादगी, अन्तर्दृष्टि','सुख ढिलाइ, भावनात्मक एकान्तता, घर तनाव, षड्यन्त्रवाद','भवन निर्माण, कृषि, भण्डार, प्रशासन','जग्गाबाट ढिलो तर दिगो लाभ, अचानक उतारचढाव','परिवारमा सादा र गम्भीर सम्बन्ध, गहिरो तर तीव्र','चतुर्थस्थो शनिर्गृहं ददाति। शनिः वृश्चिके फलं वर्धयति।','Saravali','शनिवार तिल तेल दान र शिवलिङ्गमा जल।'),
(7,4,9,'शनि चौथो भावमा घर र सुखमा ढिलाइ ल्याउँछ। जग्गा-घर पछि मिल्छ, माता दीर्घायु हुन्छन् तर भावनात्मक शान्ति ढिलो मिल्छ। सादा र अनुशासित घर वातावरण रहन्छ। शनिको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'जग्गा-घर (ढिलाइपछि), माता आयु, अनुशासन, सादगी, ज्ञान','सुख ढिलाइ, भावनात्मक एकान्तता, घर तनाव, अति विश्वास','भवन निर्माण, कृषि, भण्डार, प्रशासन','जग्गाबाट ढिलो तर दिगो लाभ, भाग्यबाट लाभ, उदार खर्च','परिवारमा सादा र गम्भीर सम्बन्ध, स्वतन्त्रता दिने','चतुर्थस्थो शनिर्गृहं ददाति। शनिः धनौ फलं वर्धयति।','Saravali','शनिवार तिल तेल दान र शिवलिङ्गमा जल।'),
(7,4,10,'शनि चौथो भावमा घर र सुखमा ढिलाइ ल्याउँछ। जग्गा-घर पछि मिल्छ, माता दीर्घायु हुन्छन् तर भावनात्मक शान्ति ढिलो मिल्छ। सादा र अनुशासित घर वातावरण रहन्छ। शनिको मकर राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'जग्गा-घर (ढिलाइपछि), माता आयु, अनुशासन, सादगी, कर्मठता','सुख ढिलाइ, भावनात्मक एकान्तता, घर तनाव, निराशावाद','भवन निर्माण, कृषि, भण्डार, प्रशासन','जग्गाबाट ढिलो तर दिगो लाभ, हौले हौले सम्पत्ति','परिवारमा सादा र गम्भीर सम्बन्ध, जिम्मेवार तर शब्द कम','चतुर्थस्थो शनिर्गृहं ददाति। शनिः मकरे फलं वर्धयति।','Saravali','शनिवार तिल तेल दान र शिवलिङ्गमा जल।'),
(7,4,11,'शनि चौथो भावमा घर र सुखमा ढिलाइ ल्याउँछ। जग्गा-घर पछि मिल्छ, माता दीर्घायु हुन्छन् तर भावनात्मक शान्ति ढिलो मिल्छ। सादा र अनुशासित घर वातावरण रहन्छ। शनिको कुम्भ राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'जग्गा-घर (ढिलाइपछि), माता आयु, अनुशासन, सादगी, नवप्रवर्तन','सुख ढिलाइ, भावनात्मक एकान्तता, घर तनाव, विद्रोहीपन','भवन निर्माण, कृषि, भण्डार, प्रशासन','जग्गाबाट ढिलो तर दिगो लाभ, नवीन तर अनियमित स्रोत','परिवारमा सादा र गम्भीर सम्बन्ध, मित्रतामा आधारित','चतुर्थस्थो शनिर्गृहं ददाति। शनिः कुम्भे फलं वर्धयति।','Saravali','शनिवार तिल तेल दान र शिवलिङ्गमा जल।'),
(7,4,12,'शनि चौथो भावमा घर र सुखमा ढिलाइ ल्याउँछ। जग्गा-घर पछि मिल्छ, माता दीर्घायु हुन्छन् तर भावनात्मक शान्ति ढिलो मिल्छ। सादा र अनुशासित घर वातावरण रहन्छ। शनिको मीन राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'जग्गा-घर (ढिलाइपछि), माता आयु, अनुशासन, सादगी, कल्पनाशक्ति','सुख ढिलाइ, भावनात्मक एकान्तता, घर तनाव, अस्पष्टता','भवन निर्माण, कृषि, भण्डार, प्रशासन','जग्गाबाट ढिलो तर दिगो लाभ, स्रोत अनिश्चित, दानशीलता','परिवारमा सादा र गम्भीर सम्बन्ध, निःशर्त प्रेम, बलिदान','चतुर्थस्थो शनिर्गृहं ददाति। शनिः मीने फलं वर्धयति।','Saravali','शनिवार तिल तेल दान र शिवलिङ्गमा जल।'),
(7,5,1,'शनि पाँचौं भावमा गम्भीर बुद्धि र पुरानो कर्मको फल दिन्छ। सन्तानमा ढिलाइ हुन सक्छ तर पछि सुख मिल्छ। विद्यामा धैर्य र गहिरो अध्ययनले सफलता दिलाउँछ। शनिको मेष राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'गम्भीर बुद्धि, गहिरो अध्ययन, पुरानो पुण्य फल, धैर्य, साहस','सन्तान ढिलाइ, उदासी, अति गम्भीरता, जल्दबाजी','अनुसन्धान, शिक्षण, ज्योतिष, खनन','पुरानो लगानीबाट फल, तर ढिलो, आत्मप्रयासबाट आय','सन्तानसँग गम्भीर तर स्थिर सम्बन्ध, ऊर्जावान तर धैर्य कम','पञ्चमस्थो शनिर्मेधावी भवति। शनिः मेषे फलं वर्धयति।','Brihat Parashara Hora Shastra','शनिवार शनि मन्त्र जप र विद्यार्थीलाई दान।'),
(7,5,2,'शनि पाँचौं भावमा गम्भीर बुद्धि र पुरानो कर्मको फल दिन्छ। सन्तानमा ढिलाइ हुन सक्छ तर पछि सुख मिल्छ। विद्यामा धैर्य र गहिरो अध्ययनले सफलता दिलाउँछ। शनिको वृषभ राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'गम्भीर बुद्धि, गहिरो अध्ययन, पुरानो पुण्य फल, धैर्य, संचय','सन्तान ढिलाइ, उदासी, अति गम्भीरता, जिद','अनुसन्धान, शिक्षण, ज्योतिष, खनन','पुरानो लगानीबाट फल, तर ढिलो, बचत र भूमि लाभ','सन्तानसँग गम्भीर तर स्थिर सम्बन्ध, वफादार र शान्त','पञ्चमस्थो शनिर्मेधावी भवति। शनिः वृषभे फलं वर्धयति।','Brihat Parashara Hora Shastra','शनिवार शनि मन्त्र जप र विद्यार्थीलाई दान।'),
(7,5,3,'शनि पाँचौं भावमा गम्भीर बुद्धि र पुरानो कर्मको फल दिन्छ। सन्तानमा ढिलाइ हुन सक्छ तर पछि सुख मिल्छ। विद्यामा धैर्य र गहिरो अध्ययनले सफलता दिलाउँछ। शनिको मिथुन राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'गम्भीर बुद्धि, गहिरो अध्ययन, पुरानो पुण्य फल, धैर्य, वाणी','सन्तान ढिलाइ, उदासी, अति गम्भीरता, द्विधा','अनुसन्धान, शिक्षण, ज्योतिष, खनन','पुरानो लगानीबाट फल, तर ढिलो, बहुआय','सन्तानसँग गम्भीर तर स्थिर सम्बन्ध, मैत्रीपूर्ण तर भावना चञ्चल','पञ्चमस्थो शनिर्मेधावी भवति। शनिः मिथुने फलं वर्धयति।','Brihat Parashara Hora Shastra','शनिवार शनि मन्त्र जप र विद्यार्थीलाई दान।'),
(7,5,4,'शनि पाँचौं भावमा गम्भीर बुद्धि र पुरानो कर्मको फल दिन्छ। सन्तानमा ढिलाइ हुन सक्छ तर पछि सुख मिल्छ। विद्यामा धैर्य र गहिरो अध्ययनले सफलता दिलाउँछ। शनिको कर्क राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'गम्भीर बुद्धि, गहिरो अध्ययन, पुरानो पुण्य फल, धैर्य, करुणा','सन्तान ढिलाइ, उदासी, अति गम्भीरता, मनोद्वन्द्व','अनुसन्धान, शिक्षण, ज्योतिष, खनन','पुरानो लगानीबाट फल, तर ढिलो, चल सम्पत्ति','सन्तानसँग गम्भीर तर स्थिर सम्बन्ध, गहिरो स्नेह र ममता','पञ्चमस्थो शनिर्मेधावी भवति। शनिः कर्के फलं वर्धयति।','Brihat Parashara Hora Shastra','शनिवार शनि मन्त्र जप र विद्यार्थीलाई दान।'),
(7,5,5,'शनि पाँचौं भावमा गम्भीर बुद्धि र पुरानो कर्मको फल दिन्छ। सन्तानमा ढिलाइ हुन सक्छ तर पछि सुख मिल्छ। विद्यामा धैर्य र गहिरो अध्ययनले सफलता दिलाउँछ। शनिको सिंह राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'गम्भीर बुद्धि, गहिरो अध्ययन, पुरानो पुण्य फल, धैर्य, नेतृत्व','सन्तान ढिलाइ, उदासी, अति गम्भीरता, अहंकार','अनुसन्धान, शिक्षण, ज्योतिष, खनन','पुरानो लगानीबाट फल, तर ढिलो, उदार खर्चसँगै प्रतिष्ठाजनक आय','सन्तानसँग गम्भीर तर स्थिर सम्बन्ध, आदर चाहने, उदार','पञ्चमस्थो शनिर्मेधावी भवति। शनिः सिंहे फलं वर्धयति।','Brihat Parashara Hora Shastra','शनिवार शनि मन्त्र जप र विद्यार्थीलाई दान।'),
(7,5,6,'शनि पाँचौं भावमा गम्भीर बुद्धि र पुरानो कर्मको फल दिन्छ। सन्तानमा ढिलाइ हुन सक्छ तर पछि सुख मिल्छ। विद्यामा धैर्य र गहिरो अध्ययनले सफलता दिलाउँछ। शनिको कन्या राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'गम्भीर बुद्धि, गहिरो अध्ययन, पुरानो पुण्य फल, धैर्य, विश्लेषण','सन्तान ढिलाइ, उदासी, अति गम्भीरता, आलोचनात्मकता','अनुसन्धान, शिक्षण, ज्योतिष, खनन','पुरानो लगानीबाट फल, तर ढिलो, योजनाबद्ध बचत','सन्तानसँग गम्भीर तर स्थिर सम्बन्ध, व्यावहारिक स्नेह, सेवा','पञ्चमस्थो शनिर्मेधावी भवति। शनिः कन्यायां फलं वर्धयति।','Brihat Parashara Hora Shastra','शनिवार शनि मन्त्र जप र विद्यार्थीलाई दान।'),
(7,5,7,'शनि पाँचौं भावमा गम्भीर बुद्धि र पुरानो कर्मको फल दिन्छ। सन्तानमा ढिलाइ हुन सक्छ तर पछि सुख मिल्छ। विद्यामा धैर्य र गहिरो अध्ययनले सफलता दिलाउँछ। शनिको तुला राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'गम्भीर बुद्धि, गहिरो अध्ययन, पुरानो पुण्य फल, धैर्य, न्याय','सन्तान ढिलाइ, उदासी, अति गम्भीरता, निर्णय ढिलाइ','अनुसन्धान, शिक्षण, ज्योतिष, खनन','पुरानो लगानीबाट फल, तर ढिलो, सन्तुलित आय','सन्तानसँग गम्भीर तर स्थिर सम्बन्ध, सामञ्जस्यपूर्ण जीवनसाथी','पञ्चमस्थो शनिर्मेधावी भवति। शनिः तुलायां फलं वर्धयति।','Brihat Parashara Hora Shastra','शनिवार शनि मन्त्र जप र विद्यार्थीलाई दान।'),
(7,5,8,'शनि पाँचौं भावमा गम्भीर बुद्धि र पुरानो कर्मको फल दिन्छ। सन्तानमा ढिलाइ हुन सक्छ तर पछि सुख मिल्छ। विद्यामा धैर्य र गहिरो अध्ययनले सफलता दिलाउँछ। शनिको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'गम्भीर बुद्धि, गहिरो अध्ययन, पुरानो पुण्य फल, धैर्य, अन्तर्दृष्टि','सन्तान ढिलाइ, उदासी, अति गम्भीरता, षड्यन्त्रवाद','अनुसन्धान, शिक्षण, ज्योतिष, खनन','पुरानो लगानीबाट फल, तर ढिलो, अचानक उतारचढाव','सन्तानसँग गम्भीर तर स्थिर सम्बन्ध, गहिरो तर तीव्र','पञ्चमस्थो शनिर्मेधावी भवति। शनिः वृश्चिके फलं वर्धयति।','Brihat Parashara Hora Shastra','शनिवार शनि मन्त्र जप र विद्यार्थीलाई दान।'),
(7,5,9,'शनि पाँचौं भावमा गम्भीर बुद्धि र पुरानो कर्मको फल दिन्छ। सन्तानमा ढिलाइ हुन सक्छ तर पछि सुख मिल्छ। विद्यामा धैर्य र गहिरो अध्ययनले सफलता दिलाउँछ। शनिको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'गम्भीर बुद्धि, गहिरो अध्ययन, पुरानो पुण्य फल, धैर्य, ज्ञान','सन्तान ढिलाइ, उदासी, अति गम्भीरता, अति विश्वास','अनुसन्धान, शिक्षण, ज्योतिष, खनन','पुरानो लगानीबाट फल, तर ढिलो, भाग्यबाट लाभ','सन्तानसँग गम्भीर तर स्थिर सम्बन्ध, स्वतन्त्रता दिने','पञ्चमस्थो शनिर्मेधावी भवति। शनिः धनौ फलं वर्धयति।','Brihat Parashara Hora Shastra','शनिवार शनि मन्त्र जप र विद्यार्थीलाई दान।'),
(7,5,10,'शनि पाँचौं भावमा गम्भीर बुद्धि र पुरानो कर्मको फल दिन्छ। सन्तानमा ढिलाइ हुन सक्छ तर पछि सुख मिल्छ। विद्यामा धैर्य र गहिरो अध्ययनले सफलता दिलाउँछ। शनिको मकर राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'गम्भीर बुद्धि, गहिरो अध्ययन, पुरानो पुण्य फल, धैर्य, कर्मठता','सन्तान ढिलाइ, उदासी, अति गम्भीरता, निराशावाद','अनुसन्धान, शिक्षण, ज्योतिष, खनन','पुरानो लगानीबाट फल, तर ढिलो, हौले हौले सम्पत्ति','सन्तानसँग गम्भीर तर स्थिर सम्बन्ध, जिम्मेवार तर शब्द कम','पञ्चमस्थो शनिर्मेधावी भवति। शनिः मकरे फलं वर्धयति।','Brihat Parashara Hora Shastra','शनिवार शनि मन्त्र जप र विद्यार्थीलाई दान।'),
(7,5,11,'शनि पाँचौं भावमा गम्भीर बुद्धि र पुरानो कर्मको फल दिन्छ। सन्तानमा ढिलाइ हुन सक्छ तर पछि सुख मिल्छ। विद्यामा धैर्य र गहिरो अध्ययनले सफलता दिलाउँछ। शनिको कुम्भ राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'गम्भीर बुद्धि, गहिरो अध्ययन, पुरानो पुण्य फल, धैर्य, नवप्रवर्तन','सन्तान ढिलाइ, उदासी, अति गम्भीरता, विद्रोहीपन','अनुसन्धान, शिक्षण, ज्योतिष, खनन','पुरानो लगानीबाट फल, तर ढिलो, नवीन तर अनियमित स्रोत','सन्तानसँग गम्भीर तर स्थिर सम्बन्ध, मित्रतामा आधारित','पञ्चमस्थो शनिर्मेधावी भवति। शनिः कुम्भे फलं वर्धयति।','Brihat Parashara Hora Shastra','शनिवार शनि मन्त्र जप र विद्यार्थीलाई दान।'),
(7,5,12,'शनि पाँचौं भावमा गम्भीर बुद्धि र पुरानो कर्मको फल दिन्छ। सन्तानमा ढिलाइ हुन सक्छ तर पछि सुख मिल्छ। विद्यामा धैर्य र गहिरो अध्ययनले सफलता दिलाउँछ। शनिको मीन राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'गम्भीर बुद्धि, गहिरो अध्ययन, पुरानो पुण्य फल, धैर्य, कल्पनाशक्ति','सन्तान ढिलाइ, उदासी, अति गम्भीरता, अस्पष्टता','अनुसन्धान, शिक्षण, ज्योतिष, खनन','पुरानो लगानीबाट फल, तर ढिलो, स्रोत अनिश्चित','सन्तानसँग गम्भीर तर स्थिर सम्बन्ध, निःशर्त प्रेम, बलिदान','पञ्चमस्थो शनिर्मेधावी भवति। शनिः मीने फलं वर्धयति।','Brihat Parashara Hora Shastra','शनिवार शनि मन्त्र जप र विद्यार्थीलाई दान।'),
(7,6,1,'शनि छैटौं भावमा धैर्य र संयमले शत्रुलाई परास्त गर्छ। सेवा र श्रममा प्रतिष्ठा मिल्छ। दीर्घ रोग हुन सक्छ तर उपचार र अनुशासनले जित्छ। शनिको मेष राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय, सेवा प्रतिष्ठा, धैर्य, ऋण मुक्ति, साहस','दीर्घ रोग, थकान, कानुनी विवाद, जल्दबाजी','सेवा, खनन, प्रशासन, चिकित्सा','ऋण ढिलो तर फिर्ता, श्रमबाट आय, आत्मप्रयासबाट आय','शत्रुसँग लामो संघर्षपछि विजय, ऊर्जावान तर धैर्य कम','षष्ठस्थो शनिर्रिपुं नाशयति। शनिः मेषे फलं वर्धयति।','Phaladeepika','शनिवार तिल तेल दान र शनि मन्त्र जप।'),
(7,6,2,'शनि छैटौं भावमा धैर्य र संयमले शत्रुलाई परास्त गर्छ। सेवा र श्रममा प्रतिष्ठा मिल्छ। दीर्घ रोग हुन सक्छ तर उपचार र अनुशासनले जित्छ। शनिको वृषभ राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय, सेवा प्रतिष्ठा, धैर्य, ऋण मुक्ति, संचय','दीर्घ रोग, थकान, कानुनी विवाद, जिद','सेवा, खनन, प्रशासन, चिकित्सा','ऋण ढिलो तर फिर्ता, श्रमबाट आय, बचत र भूमि लाभ','शत्रुसँग लामो संघर्षपछि विजय, वफादार र शान्त','षष्ठस्थो शनिर्रिपुं नाशयति। शनिः वृषभे फलं वर्धयति।','Phaladeepika','शनिवार तिल तेल दान र शनि मन्त्र जप।'),
(7,6,3,'शनि छैटौं भावमा धैर्य र संयमले शत्रुलाई परास्त गर्छ। सेवा र श्रममा प्रतिष्ठा मिल्छ। दीर्घ रोग हुन सक्छ तर उपचार र अनुशासनले जित्छ। शनिको मिथुन राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय, सेवा प्रतिष्ठा, धैर्य, ऋण मुक्ति, वाणी','दीर्घ रोग, थकान, कानुनी विवाद, द्विधा','सेवा, खनन, प्रशासन, चिकित्सा','ऋण ढिलो तर फिर्ता, श्रमबाट आय, बहुआय','शत्रुसँग लामो संघर्षपछि विजय, मैत्रीपूर्ण तर भावना चञ्चल','षष्ठस्थो शनिर्रिपुं नाशयति। शनिः मिथुने फलं वर्धयति।','Phaladeepika','शनिवार तिल तेल दान र शनि मन्त्र जप।'),
(7,6,4,'शनि छैटौं भावमा धैर्य र संयमले शत्रुलाई परास्त गर्छ। सेवा र श्रममा प्रतिष्ठा मिल्छ। दीर्घ रोग हुन सक्छ तर उपचार र अनुशासनले जित्छ। शनिको कर्क राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय, सेवा प्रतिष्ठा, धैर्य, ऋण मुक्ति, करुणा','दीर्घ रोग, थकान, कानुनी विवाद, मनोद्वन्द्व','सेवा, खनन, प्रशासन, चिकित्सा','ऋण ढिलो तर फिर्ता, श्रमबाट आय, चल सम्पत्ति','शत्रुसँग लामो संघर्षपछि विजय, गहिरो स्नेह र ममता','षष्ठस्थो शनिर्रिपुं नाशयति। शनिः कर्के फलं वर्धयति।','Phaladeepika','शनिवार तिल तेल दान र शनि मन्त्र जप।'),
(7,6,5,'शनि छैटौं भावमा धैर्य र संयमले शत्रुलाई परास्त गर्छ। सेवा र श्रममा प्रतिष्ठा मिल्छ। दीर्घ रोग हुन सक्छ तर उपचार र अनुशासनले जित्छ। शनिको सिंह राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय, सेवा प्रतिष्ठा, धैर्य, ऋण मुक्ति, नेतृत्व','दीर्घ रोग, थकान, कानुनी विवाद, अहंकार','सेवा, खनन, प्रशासन, चिकित्सा','ऋण ढिलो तर फिर्ता, श्रमबाट आय, उदार खर्चसँगै प्रतिष्ठाजनक आय','शत्रुसँग लामो संघर्षपछि विजय, आदर चाहने, उदार','षष्ठस्थो शनिर्रिपुं नाशयति। शनिः सिंहे फलं वर्धयति।','Phaladeepika','शनिवार तिल तेल दान र शनि मन्त्र जप।'),
(7,6,6,'शनि छैटौं भावमा धैर्य र संयमले शत्रुलाई परास्त गर्छ। सेवा र श्रममा प्रतिष्ठा मिल्छ। दीर्घ रोग हुन सक्छ तर उपचार र अनुशासनले जित्छ। शनिको कन्या राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय, सेवा प्रतिष्ठा, धैर्य, ऋण मुक्ति, विश्लेषण','दीर्घ रोग, थकान, कानुनी विवाद, आलोचनात्मकता','सेवा, खनन, प्रशासन, चिकित्सा','ऋण ढिलो तर फिर्ता, श्रमबाट आय, योजनाबद्ध बचत','शत्रुसँग लामो संघर्षपछि विजय, व्यावहारिक स्नेह, सेवा','षष्ठस्थो शनिर्रिपुं नाशयति। शनिः कन्यायां फलं वर्धयति।','Phaladeepika','शनिवार तिल तेल दान र शनि मन्त्र जप।'),
(7,6,7,'शनि छैटौं भावमा धैर्य र संयमले शत्रुलाई परास्त गर्छ। सेवा र श्रममा प्रतिष्ठा मिल्छ। दीर्घ रोग हुन सक्छ तर उपचार र अनुशासनले जित्छ। शनिको तुला राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय, सेवा प्रतिष्ठा, धैर्य, ऋण मुक्ति, न्याय','दीर्घ रोग, थकान, कानुनी विवाद, निर्णय ढिलाइ','सेवा, खनन, प्रशासन, चिकित्सा','ऋण ढिलो तर फिर्ता, श्रमबाट आय, सन्तुलित आय','शत्रुसँग लामो संघर्षपछि विजय, सामञ्जस्यपूर्ण जीवनसाथी','षष्ठस्थो शनिर्रिपुं नाशयति। शनिः तुलायां फलं वर्धयति।','Phaladeepika','शनिवार तिल तेल दान र शनि मन्त्र जप।'),
(7,6,8,'शनि छैटौं भावमा धैर्य र संयमले शत्रुलाई परास्त गर्छ। सेवा र श्रममा प्रतिष्ठा मिल्छ। दीर्घ रोग हुन सक्छ तर उपचार र अनुशासनले जित्छ। शनिको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय, सेवा प्रतिष्ठा, धैर्य, ऋण मुक्ति, अन्तर्दृष्टि','दीर्घ रोग, थकान, कानुनी विवाद, षड्यन्त्रवाद','सेवा, खनन, प्रशासन, चिकित्सा','ऋण ढिलो तर फिर्ता, श्रमबाट आय, अचानक उतारचढाव','शत्रुसँग लामो संघर्षपछि विजय, गहिरो तर तीव्र','षष्ठस्थो शनिर्रिपुं नाशयति। शनिः वृश्चिके फलं वर्धयति।','Phaladeepika','शनिवार तिल तेल दान र शनि मन्त्र जप।'),
